const LANDING_HTML = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta property=\"og:title\" content=\"Quilliam: handwritten letters, certified human\"><meta property=\"og:description\" content=\"Write a letter by hand on holiday paper, seal it in wax and send it as a link. Quilliam the owl certifies every letter a real person wrote.\"><style>:root{padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}body{margin:0}[hidden]{display:none!important}img{max-width:100%}</style><script>window.QUILLIAM_API=\"\";<\/script></head><body><title>Quilliam</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<meta name=\"description\" content=\"Write a letter by hand on holiday paper, seal it in wax and send it as a link. Quilliam the owl certifies every letter a real person wrote.\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Caveat:wght@500;700&family=Cormorant+Garamond:ital,wght@1,500;1,600&family=Fraunces:ital,opsz,wght@1,9..144,600;1,9..144,800&family=Manrope:wght@400;500;600;700;800&family=Special+Elite&family=Pinyon+Script&display=swap\">\n<style>\n/* Layout: the page is a writing desk at night. One lit letter carries the hero; sections below sit on the desk like stationery laid out in a row. Single dark look by choice, matching the app. */\n:root{\n  --desk:#17120f; --desk-2:#211a15; --desk-3:#2b221b; --line:#3a3029; --muted:#a8998b; --text:#f3e9dc;\n  --paper:#f6ecd8; --paper-ink:#2c1f14; --gold:#e3a83c; --gold-soft:#e3a83c22; --wax:#b3341f; --wax-2:#86200f; --ok:#5cc495; --rose:#f29bb8;\n  --f-display:\"Fraunces\",\"Cormorant Garamond\",Georgia,serif;\n  --f-body:\"Manrope\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --f-hand:\"Caveat\",\"Segoe Print\",\"Bradley Hand\",cursive;\n  --f-label:\"Special Elite\",\"Courier New\",monospace;\n  --f-quote:\"Cormorant Garamond\",Georgia,serif;\n  color-scheme:dark;\n}\nhtml{scroll-behavior:smooth}\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\nhtml,body{background:var(--desk);color:var(--text)}\nbody{font-family:var(--f-body);font-size:16px;line-height:1.6;background:radial-gradient(1100px 620px at 72% -8%,#4a331f66,transparent 70%),radial-gradient(800px 500px at -10% 40%,#3a1c1430,transparent 70%),var(--desk)}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:40;background:var(--desk)}\na{color:inherit}\n:focus-visible{outline:2px solid var(--gold);outline-offset:3px;border-radius:4px}\n.wrap{max-width:1160px;margin:0 auto;padding-left:max(20px,env(safe-area-inset-left,0px));padding-right:max(20px,env(safe-area-inset-right,0px))}\n.label{font-family:var(--f-label);font-size:12px;letter-spacing:.2em;text-transform:uppercase;color:var(--gold);margin:0}\nh1,h2,h3{font-family:var(--f-display);font-style:italic;font-weight:800;line-height:1.02;letter-spacing:-.015em;margin:0;text-wrap:balance}\nh2{font-size:clamp(34px,4.6vw,54px)}\nh3{font-size:24px;font-weight:600}\np{margin:0}\n.lede{font-size:clamp(17px,1.6vw,19px);color:#d9cbbb;max-width:56ch}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border-radius:12px;padding:14px 22px;font-weight:700;font-size:16px;text-decoration:none;border:1px solid var(--line);background:var(--desk-2);color:var(--text);cursor:pointer;font-family:inherit}\n.btn:hover{border-color:#6b5a48}\n.btn.wax{background:linear-gradient(180deg,var(--wax),var(--wax-2));border-color:var(--wax);color:#fff4ea;box-shadow:0 10px 26px #b3341f44}\n.btn.wax:hover{filter:brightness(1.07)}\nsection{padding-block:clamp(64px,9vw,112px)}\n\n/* Nav */\n.nav{position:sticky;top:env(safe-area-inset-top,0px);z-index:30;background:#17120fe6;backdrop-filter:blur(10px);border-bottom:1px solid #2a221c}\n.nav .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-block:12px}\n.brand{display:flex;align-items:center;gap:10px;text-decoration:none}\n.brand svg{width:34px;height:38px}\n.brand span{font-family:var(--f-display);font-style:italic;font-weight:800;font-size:26px;letter-spacing:-.01em}\n.navlinks{display:flex;align-items:center;gap:22px;font-size:14px;font-weight:600;color:var(--muted)}\n.navlinks a{text-decoration:none}\n.navlinks a:hover{color:var(--text)}\n.navlinks .btn{padding:9px 16px;font-size:14px;color:#fff4ea}\n@media (max-width:760px){.navlinks a:not(.btn){display:none}}\n\n/* Hero */\n.hero{padding-block:clamp(40px,7vw,90px) clamp(56px,8vw,100px)}\n.hero .wrap{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:clamp(32px,5vw,72px);align-items:center}\n@media (max-width:900px){.hero .wrap{grid-template-columns:minmax(0,1fr)}}\n.hero-copy{display:grid;gap:22px;min-width:0}\n.hero h1{font-size:clamp(46px,7.2vw,92px)}\n.hero h1 em{font-style:normal;font-family:var(--f-hand);font-weight:700;color:var(--gold);font-size:1.12em;letter-spacing:0;display:inline-block;transform:rotate(-2deg)}\n.hero-cta{display:flex;flex-wrap:wrap;gap:12px;align-items:center}\n.fineprint{font-size:13px;color:var(--muted)}\n.badge{display:inline-flex;align-items:center;gap:8px;border:1px solid #2f6b50;background:#10241a;color:#9be7c2;border-radius:999px;padding:6px 14px;font-size:13px;font-weight:700;justify-self:start}\n\n.stage{position:relative;min-width:0;padding:10px 0 60px;overflow-x:clip}\n@media (max-width:520px){.stamp{right:2%}}\n.letter{position:relative;background:linear-gradient(180deg,#21402f,#152b20);color:#f3e6c4;border-radius:6px;aspect-ratio:4/5;max-width:520px;margin-inline:auto;padding:9% 9% 8%;box-shadow:0 40px 80px #000a,0 0 0 1px #ffffff0d inset;transform:rotate(2deg);display:grid;grid-template-rows:auto auto 1fr auto;gap:4%}\n.letter::before{content:\"\";position:absolute;inset:0;border-radius:6px;pointer-events:none;background:linear-gradient(#c9a14a,#c9a14a) top/100% 7px no-repeat,linear-gradient(#a3272a,#a3272a) 0 7px/100% 3px no-repeat,linear-gradient(#c9a14a,#c9a14a) bottom/100% 7px no-repeat}\n.l-date{justify-self:end;font-family:var(--f-quote);font-style:italic;font-size:clamp(13px,1.4vw,16px);opacity:.75}\n.l-greet{font-family:\"Pinyon Script\",cursive;font-size:clamp(26px,3.2vw,38px);line-height:1.1}\n.l-body{font-family:var(--f-hand);font-size:clamp(21px,2.35vw,29px);line-height:1.32;min-width:0}\n.ink{background:linear-gradient(90deg,#000 50%,transparent 0) 0 0/200% 100%;-webkit-background-clip:text;background-clip:text}\n.l-body p{clip-path:inset(0 100% 0 0);animation:write 1.6s cubic-bezier(.5,.1,.4,1) forwards}\n.l-body p:nth-child(2){animation-delay:1.4s}\n.l-body p:nth-child(3){animation-delay:2.8s}\n@keyframes write{to{clip-path:inset(0 0 0 0)}}\n@media (prefers-reduced-motion:reduce){.l-body p{animation:none;clip-path:none}}\n.l-sign{justify-self:end;text-align:right;font-family:var(--f-quote);font-style:italic;font-size:clamp(15px,1.6vw,19px)}\n.l-sign b{display:block;font-family:var(--f-hand);font-weight:700;font-size:1.7em;line-height:1;font-style:normal}\n.seal{position:absolute;left:6%;bottom:6%;width:17%;filter:drop-shadow(0 6px 10px #0007)}\n.stamp{position:absolute;right:-4%;top:9%;width:30%;transform:rotate(-14deg);animation:stampin .5s cubic-bezier(.2,1.6,.4,1) 4.4s both}\n@keyframes stampin{from{transform:rotate(-14deg) scale(1.8);opacity:0}to{transform:rotate(-14deg) scale(1);opacity:1}}\n@media (prefers-reduced-motion:reduce){.stamp{animation:none}}\n.sticker{position:absolute;width:13%;filter:drop-shadow(0 4px 6px #0006)}\n.owlperch{position:absolute;right:2%;bottom:0;display:flex;align-items:flex-end;gap:10px;max-width:min(330px,80%)}\n.owlperch svg{width:86px;height:98px;flex:none;filter:drop-shadow(0 10px 18px #0009)}\n.bubble{background:#fbf3df;color:#3b2412;border-radius:16px 16px 4px 16px;padding:11px 14px;font-family:var(--f-quote);font-style:italic;font-size:17px;line-height:1.3;box-shadow:0 14px 30px #0009;border:1px solid #e8c77f}\n@media (max-width:520px){.owlperch{right:0}.owlperch svg{width:64px;height:74px}.bubble{font-size:15px}}\n\n/* Occasion strip */\n.strip{border-block:1px solid #2a221c;background:#1b1511;overflow:hidden}\n.strip .wrap{display:flex;flex-wrap:wrap;gap:10px 26px;justify-content:center;padding-block:18px;font-family:var(--f-display);font-style:italic;font-weight:600;font-size:clamp(17px,1.8vw,21px);color:#d6c4ae}\n.strip span{white-space:nowrap}\n.strip i{font-style:normal;color:var(--gold);margin-left:26px}\n\n/* Steps */\n.head{display:grid;gap:14px;margin-bottom:clamp(36px,5vw,56px);max-width:760px}\n.steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;counter-reset:s}\n@media (max-width:820px){.steps{grid-template-columns:minmax(0,1fr)}}\n.step{display:grid;gap:12px;align-content:start}\n.step .num{font-family:var(--f-label);color:var(--gold);font-size:13px;letter-spacing:.18em}\n.step .pic{aspect-ratio:16/10;border-radius:14px;background:var(--desk-2);border:1px solid var(--line);display:grid;place-items:center;overflow:hidden;position:relative}\n.step p{color:#d0c2b2}\n.swatches{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;width:80%}\n.swatches div{aspect-ratio:3/4;border-radius:4px;box-shadow:0 6px 12px #0006}\n.pad{width:78%;aspect-ratio:16/9;background:var(--paper);border-radius:4px;position:relative;box-shadow:0 8px 18px #0007}\n.pad svg{position:absolute;inset:0;width:100%;height:100%}\n.pad .finger{position:absolute;right:16%;bottom:10%;width:34px;height:34px;border-radius:50%;background:#ffffff2e;border:2px solid #fff8}\n.share{display:grid;gap:8px;width:80%}\n.share .url{background:#100c0a;border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-family:var(--f-label);font-size:12px;color:#d6c4ae;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.share .row{display:flex;gap:8px;align-items:center}\n.share .row img{width:40px}\n.share .row span{font-size:13px;font-weight:700;color:#9be7c2}\n\n/* Demo */\n.demo{background:linear-gradient(180deg,#1d1612,#17120f)}\n.demo .wrap{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(32px,5vw,64px);align-items:center}\n@media (max-width:900px){.demo .wrap{grid-template-columns:minmax(0,1fr)}}\n.demo-copy{display:grid;gap:18px;min-width:0}\n.demo-copy ul{margin:0;padding-left:20px;color:#d0c2b2;display:grid;gap:8px}\n.desk{background:var(--paper);color:var(--paper-ink);border-radius:8px;padding:22px;display:grid;gap:14px;box-shadow:0 30px 60px #000a;min-width:0}\n.desk label{font-family:var(--f-label);font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#8a6a3a}\n.desk textarea{width:100%;box-sizing:border-box;min-height:140px;resize:vertical;border:0;border-radius:4px;background:repeating-linear-gradient(transparent 0 33px,#c9b48f66 33px 34px);font-family:var(--f-hand);font-size:25px;line-height:34px;color:var(--paper-ink);padding:2px 4px}\n.desk textarea:focus{outline:2px solid #c9952e}\n.trybtns{display:flex;flex-wrap:wrap;gap:8px}\n.trybtns button{border:1px solid #c9b48f;background:#efe2c6;color:#5a3a1a;border-radius:999px;padding:7px 14px;font-weight:700;font-size:13px;font-family:inherit;cursor:pointer}\n.trybtns button:hover{background:#e8d6b1}\n.verdict{display:flex;gap:12px;align-items:flex-start;background:#fbf3df;border:1px solid #e8c77f;border-radius:14px;padding:12px 14px}\n.verdict svg{width:48px;height:55px;flex:none}\n.verdict p{font-family:var(--f-quote);font-style:italic;font-size:19px;line-height:1.3;color:#3b2412}\n.meter{display:grid;gap:5px}\n.bar{position:relative;height:10px;border-radius:99px;background:linear-gradient(90deg,#3aa76d,#e2c04a 50%,#d9483b)}\n.pin{position:absolute;top:-4px;width:7px;height:18px;border-radius:3px;background:#2a1a0c;border:2px solid var(--paper);transform:translateX(-50%);left:50%;transition:left .5s cubic-bezier(.3,1.4,.5,1)}\n@media (prefers-reduced-motion:reduce){.pin{transition:none}}\n.scale{display:flex;justify-content:space-between;font-family:var(--f-label);font-size:10px;letter-spacing:.1em;color:#7b5a3a;text-transform:uppercase}\n\n/* Papers */\n.papers{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}\n@media (max-width:900px){.papers{grid-template-columns:repeat(2,minmax(0,1fr))}}\n.pc{display:grid;gap:10px}\n.pc .sheet{aspect-ratio:4/5;border-radius:5px;padding:14% 12%;box-shadow:0 18px 34px #0008;position:relative;overflow:hidden;display:grid;align-content:start;gap:8%}\n.pc .sheet b{font-weight:400;font-size:clamp(18px,2vw,24px);line-height:1.1}\n.pc .sheet i{display:block;height:2px;border-radius:2px;opacity:.28;background:currentColor}\n.pc .sheet i:nth-of-type(2){width:86%}.pc .sheet i:nth-of-type(3){width:64%}\n.pc strong{font-size:15px}\n.pc small{display:block;color:var(--muted);font-size:13px;margin-top:-6px}\n.more{margin-top:26px;color:var(--muted);font-size:15px}\n.more b{color:var(--text)}\n\n/* Pricing */\n.plans{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;align-items:stretch}\n@media (max-width:980px){.plans{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media (max-width:520px){.plans{grid-template-columns:minmax(0,1fr)}}\n.plan{border:1px solid var(--line);background:var(--desk-2);border-radius:18px;padding:22px;display:grid;gap:14px;align-content:start;grid-template-rows:auto auto auto 1fr auto}\n.plan.best{border-color:var(--gold);box-shadow:0 0 0 4px var(--gold-soft);background:linear-gradient(180deg,#2c2216,var(--desk-2))}\n.plan .pn{font-weight:800;font-size:15px;display:flex;justify-content:space-between;gap:8px;align-items:center}\n.plan .tag{font-family:var(--f-label);font-size:10px;letter-spacing:.14em;color:var(--gold);text-transform:uppercase}\n.plan .price{font-family:var(--f-display);font-style:italic;font-weight:800;font-size:46px;line-height:1;font-variant-numeric:tabular-nums}\n.plan .price small{font-family:var(--f-body);font-style:normal;font-size:14px;font-weight:500;color:var(--muted)}\n.plan .per{font-size:13px;color:var(--muted);margin-top:-6px}\n.plan ul{margin:0;padding-left:18px;color:#d0c2b2;font-size:15px;display:grid;gap:6px}\n.plan .btn{width:100%;box-sizing:border-box;font-size:15px;padding:12px}\n.plan.best .btn{background:var(--gold);border-color:var(--gold);color:#1b1208}\n\n/* Business */\n.biz .wrap{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(32px,5vw,64px);align-items:start}\n@media (max-width:900px){.biz .wrap{grid-template-columns:minmax(0,1fr)}}\n.biz-copy{display:grid;gap:20px;min-width:0}\n.uses{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n@media (max-width:520px){.uses{grid-template-columns:minmax(0,1fr)}}\n.uses div{border-top:1px solid var(--line);padding-top:10px}\n.uses b{display:block;font-size:15px}\n.uses span{font-size:14px;color:var(--muted)}\n.lh{background:#fff;color:#1e2a3a;border-radius:6px;overflow:hidden;box-shadow:0 30px 60px #000a;display:grid;grid-template-rows:auto 1fr auto;aspect-ratio:5/4;max-width:100%}\n.lh-head{display:flex;align-items:center;gap:12px;padding:18px 22px 12px;border-bottom:5px solid #1f4fa8}\n.lh-logo{width:38px;height:38px;border-radius:8px;background:#1f4fa8;color:#fff;display:grid;place-items:center;font-weight:800;font-size:18px}\n.lh-name{font-weight:800;color:#1f4fa8;font-size:17px;line-height:1.1}\n.lh-name small{display:block;font-weight:500;color:#5a6a80;font-size:12px}\n.lh-body{padding:16px 22px;font-family:var(--f-hand);font-size:clamp(19px,2.1vw,24px);line-height:1.3;color:#1e2a3a;position:relative}\n.lh-foot{background:#1f4fa8;color:#fff;font-size:12px;padding:9px 22px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}\n.form{border:1px solid var(--line);background:var(--desk-2);border-radius:18px;padding:22px;display:grid;gap:14px;margin-top:22px}\n.form h3{font-size:22px}\n.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n@media (max-width:520px){.fields{grid-template-columns:minmax(0,1fr)}}\n.form label{display:grid;gap:5px;font-size:13px;color:var(--muted);font-weight:600}\n.form input,.form select{background:var(--desk);border:1px solid var(--line);border-radius:10px;padding:11px 12px;color:var(--text);font:inherit;font-size:15px;width:100%;box-sizing:border-box}\n.formmsg{font-size:14px;margin:0}\n.formmsg.ok{color:var(--ok)} .formmsg.err{color:#ff9b8a}\n\n/* Mail */\n.mail .card{border-radius:22px;background:linear-gradient(135deg,#f6e7d0,#e9cfaa);color:#4a2b12;padding:clamp(24px,4vw,44px);display:grid;grid-template-columns:auto minmax(0,1fr);gap:clamp(20px,4vw,44px);align-items:center;position:relative;overflow:hidden}\n@media (max-width:720px){.mail .card{grid-template-columns:minmax(0,1fr)}}\n.mail .card::before{content:\"\";position:absolute;inset:0 0 auto;height:10px;background:repeating-linear-gradient(135deg,#c0392b 0 14px,transparent 14px 22px,#1f4fa8 22px 36px,transparent 36px 44px)}\n.mail h2{color:#3a1f0b}\n.mail p{color:#6b4423}\n.mail .env{width:clamp(110px,16vw,170px)}\n.mail form{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}\n.mail input{flex:1 1 220px;min-width:0;border:1px solid #c9a878;background:#fffaf0;border-radius:12px;padding:13px 14px;font:inherit;color:#3a1f0b}\n.mail .formmsg.ok{color:#1f6b45} .mail .formmsg.err{color:#a3271a}\n\n/* FAQ */\n.faq{display:grid;gap:10px;max-width:820px}\n.faq details{border:1px solid var(--line);background:var(--desk-2);border-radius:14px;padding:4px 18px}\n.faq summary{cursor:pointer;font-weight:700;font-size:17px;padding:14px 0;list-style:none;display:flex;justify-content:space-between;gap:12px}\n.faq summary::-webkit-details-marker{display:none}\n.faq summary::after{content:\"+\";color:var(--gold);font-size:22px;line-height:1}\n.faq details[open] summary::after{content:\"–\"}\n.faq details p{color:#d0c2b2;padding-bottom:16px;max-width:68ch}\n\n/* Final CTA + footer */\n.final{text-align:center}\n.final .wrap{display:grid;gap:20px;justify-items:center}\n.final h2{font-size:clamp(38px,6vw,72px)}\nfooter{border-top:1px solid #2a221c;padding-block:28px 40px;color:var(--muted);font-size:14px}\nfooter .wrap{display:flex;flex-wrap:wrap;gap:12px 24px;justify-content:space-between;align-items:center}\nfooter nav{display:flex;gap:18px;flex-wrap:wrap}\nfooter a{text-decoration:none} footer a:hover{color:var(--text)}\n</style>\n\n<header class=\"nav\">\n  <div class=\"wrap\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"Quilliam home\">\n      <svg viewBox=\"0 0 84 96\" aria-hidden=\"true\"><path d=\"M20 22 L14 6 L30 16Z M64 22 L70 6 L54 16Z\" fill=\"#6b4524\"/><ellipse cx=\"42\" cy=\"56\" rx=\"30\" ry=\"36\" fill=\"#8a5a2f\"/><ellipse cx=\"42\" cy=\"66\" rx=\"19\" ry=\"23\" fill=\"#e9cf9f\"/><circle cx=\"29\" cy=\"38\" r=\"12\" fill=\"#f6ead0\"/><circle cx=\"55\" cy=\"38\" r=\"12\" fill=\"#f6ead0\"/><circle cx=\"29\" cy=\"39\" r=\"6\" fill=\"#2a1a0c\"/><circle cx=\"55\" cy=\"39\" r=\"6\" fill=\"#2a1a0c\"/><circle cx=\"29\" cy=\"38\" r=\"13\" fill=\"none\" stroke=\"#c9a14a\" stroke-width=\"2\"/><circle cx=\"55\" cy=\"38\" r=\"13\" fill=\"none\" stroke=\"#c9a14a\" stroke-width=\"2\"/><path d=\"M38 48 L46 48 L42 56Z\" fill=\"#e0a63a\"/></svg>\n      <span>Quilliam</span>\n    </a>\n    <nav class=\"navlinks\" aria-label=\"Main\">\n      <a href=\"#how\">How it works</a>\n      <a href=\"#papers\">Papers</a>\n      <a href=\"#pricing\">Pricing</a>\n      <a href=\"#business\">For business</a>\n      <a class=\"btn wax write-link\" href=\"/write\">Write a letter</a>\n    </nav>\n  </div>\n</header>\n\n<main id=\"top\">\n  <section class=\"hero\">\n    <div class=\"wrap\">\n      <div class=\"hero-copy\">\n        <span class=\"badge\">✓ Human-written letters only</span>\n        <h1>Write it by <em>hand.</em> Quilliam will know.</h1>\n        <p class=\"lede\">Pick holiday paper, write with your finger or stylus, press a wax seal and send it as a link. Quilliam the owl reads over your shoulder and stamps every letter a real person wrote.</p>\n        <div class=\"hero-cta\">\n          <a class=\"btn wax write-link\" href=\"/write\">Write your first letter free</a>\n          <a class=\"btn\" href=\"#pricing\">See pricing</a>\n        </div>\n        <p class=\"fineprint\">Your first letter is free. No account, no app to download.</p>\n      </div>\n\n      <div class=\"stage\" aria-label=\"An example letter on Evergreen holiday paper\">\n        <div class=\"letter\">\n          <div class=\"l-date\">24 December 2026</div>\n          <div class=\"l-greet\">Dearest Maya,</div>\n          <div class=\"l-body\">\n            <p>The lights went up on our street tonight</p>\n            <p>and I thought of our walk last year,</p>\n            <p>the one where we got lost. Come home soon.</p>\n          </div>\n          <div class=\"l-sign\">Merry Christmas, with love,<b>Raj</b></div>\n          <img class=\"seal\" id=\"heroSeal\" alt=\"\">\n          <img class=\"stamp\" id=\"heroStamp\" alt=\"Quilliam certified stamp\">\n          <img class=\"sticker\" id=\"heroStk1\" alt=\"\" style=\"right:10%;bottom:20%;transform:rotate(12deg)\">\n          <img class=\"sticker\" id=\"heroStk2\" alt=\"\" style=\"left:-5%;top:28%;transform:rotate(-16deg);width:11%\">\n        </div>\n        <div class=\"owlperch\" aria-hidden=\"true\">\n          <div class=\"bubble\">“Crooked loops and a real memory. Stamp awarded.”</div>\n          <svg viewBox=\"0 0 84 96\"><path d=\"M20 22 L14 6 L30 16Z M64 22 L70 6 L54 16Z\" fill=\"#6b4524\"/><ellipse cx=\"42\" cy=\"56\" rx=\"30\" ry=\"36\" fill=\"#8a5a2f\"/><ellipse cx=\"42\" cy=\"66\" rx=\"19\" ry=\"23\" fill=\"#e9cf9f\"/><path d=\"M30 60 q4 4 8 0 M38 68 q4 4 8 0 M46 60 q4 4 8 0 M34 76 q4 4 8 0 M42 76 q4 4 8 0\" stroke=\"#b88a52\" stroke-width=\"1.6\" fill=\"none\"/><path d=\"M12 54 q-6 18 8 30 q4-16 2-30Z M72 54 q6 18-8 30 q-4-16-2-30Z\" fill=\"#6b4524\"/><circle cx=\"29\" cy=\"38\" r=\"12\" fill=\"#f6ead0\"/><circle cx=\"55\" cy=\"38\" r=\"12\" fill=\"#f6ead0\"/><circle cx=\"29\" cy=\"39\" r=\"6\" fill=\"#2a1a0c\"/><circle cx=\"55\" cy=\"39\" r=\"6\" fill=\"#2a1a0c\"/><circle cx=\"31\" cy=\"37\" r=\"1.8\" fill=\"#fff\"/><circle cx=\"57\" cy=\"37\" r=\"1.8\" fill=\"#fff\"/><circle cx=\"29\" cy=\"38\" r=\"13\" fill=\"none\" stroke=\"#c9a14a\" stroke-width=\"1.6\"/><circle cx=\"55\" cy=\"38\" r=\"13\" fill=\"none\" stroke=\"#c9a14a\" stroke-width=\"1.6\"/><rect x=\"18\" y=\"22\" width=\"20\" height=\"3\" rx=\"1.5\" fill=\"#4a2c14\"/><rect x=\"46\" y=\"22\" width=\"20\" height=\"3\" rx=\"1.5\" fill=\"#4a2c14\"/><path d=\"M38 48 L46 48 L42 56Z\" fill=\"#e0a63a\"/><path d=\"M66 86 L80 52 q2-6 -2-4 L64 82Z\" fill=\"#f2ead8\" stroke=\"#b49a6a\" stroke-width=\"1\"/><path d=\"M30 90 h8 M46 90 h8\" stroke=\"#e0a63a\" stroke-width=\"3\" stroke-linecap=\"round\"/></svg>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <div class=\"strip\" aria-label=\"Occasions\">\n    <div class=\"wrap\">\n      <span>Christmas</span><span>Hanukkah</span><span>Diwali</span><span>Thanksgiving</span><span>New Year’s Eve</span><span>Birthdays</span><span>Anniversaries</span><span>Roast cards</span><span>Travel postcards</span><span>Client thank-yous</span>\n    </div>\n  </div>\n\n  <section id=\"how\">\n    <div class=\"wrap\">\n      <div class=\"head\">\n        <p class=\"label\">How it works</p>\n        <h2>Three minutes, one real letter</h2>\n      </div>\n      <div class=\"steps\">\n        <div class=\"step\">\n          <div class=\"pic\"><div class=\"swatches\" id=\"stepSwatches\"></div></div>\n          <span class=\"num\">STEP 1</span>\n          <h3>Pick paper and a layout</h3>\n          <p>Thirty-plus papers from candy-cane stripes to Diwali glow, in classic, note card, postcard, travel card, roast card or company letterhead layouts.</p>\n        </div>\n        <div class=\"step\">\n          <div class=\"pic\"><div class=\"pad\"><svg viewBox=\"0 0 320 180\" aria-hidden=\"true\"><path d=\"M30 70c10-20 22-24 26-8s-10 30-4 30 14-26 22-26 4 26 12 26 10-22 18-22 2 22 12 22c8 0 12-20 20-20s-2 18 8 18 14-24 22-24-4 24 6 24c8 0 10-14 16-14\" fill=\"none\" stroke=\"#2c1f14\" stroke-width=\"3.2\" stroke-linecap=\"round\"/><path d=\"M30 120c12-14 20-14 22 0s14-16 22-12 2 14 12 12 14-16 22-12 0 14 12 12c10-2 10-12 18-12\" fill=\"none\" stroke=\"#2c1f14\" stroke-width=\"3.2\" stroke-linecap=\"round\"/></svg><span class=\"finger\"></span></div></div>\n          <span class=\"num\">STEP 2</span>\n          <h3>Write it by hand</h3>\n          <p>Use your finger, a stylus or a mouse. Add stickers, pin a polaroid and choose a wax seal. Prefer typing? That works too, and Quilliam still checks.</p>\n        </div>\n        <div class=\"step\">\n          <div class=\"pic\"><div class=\"share\"><div class=\"url\">…/l/9fQ2kLxV7mTqR4nB</div><div class=\"row\"><img id=\"stepStamp\" alt=\"\"><span>Certified human-written</span></div></div></div>\n          <span class=\"num\">STEP 3</span>\n          <h3>Seal it and send the link</h3>\n          <p>Send it by text, WhatsApp or email. Your person opens the letter, sees Quilliam’s stamp, and can write one straight back.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"demo\" id=\"quilliam\">\n    <div class=\"wrap\">\n      <div class=\"demo-copy\">\n        <p class=\"label\">Meet Quilliam</p>\n        <h2>He praises real ink and roasts robot mush</h2>\n        <p class=\"lede\">Quilliam watches how a letter gets written: the pauses, the crossings-out, the wobbly loops. Pasted paragraphs and chatbot phrases move his meter toward “robot slop.”</p>\n        <ul>\n          <li>His stamp is earned from how you wrote, never from a guess about your words.</li>\n          <li>He roasts the robot, never the person.</li>\n          <li>Letters about loss or apologies get gentleness, not jokes.</li>\n        </ul>\n      </div>\n      <div class=\"desk\">\n        <label for=\"tryText\">Try him: write a line, or paste one</label>\n        <textarea id=\"tryText\" placeholder=\"Dear Mom, the kitchen smelled like cardamom today…\"></textarea>\n        <div class=\"trybtns\">\n          <button type=\"button\" id=\"tryHuman\">Try a real line</button>\n          <button type=\"button\" id=\"tryRobot\">Try a chatbot line</button>\n          <button type=\"button\" id=\"tryClear\">Clear</button>\n        </div>\n        <div class=\"meter\" aria-hidden=\"true\">\n          <div class=\"bar\"><div class=\"pin\" id=\"tryPin\"></div></div>\n          <div class=\"scale\"><span>Human soul</span><span>Robot slop</span></div>\n        </div>\n        <div class=\"verdict\" role=\"status\" aria-live=\"polite\">\n          <svg viewBox=\"0 0 84 96\" aria-hidden=\"true\"><path d=\"M20 22 L14 6 L30 16Z M64 22 L70 6 L54 16Z\" fill=\"#6b4524\"/><ellipse cx=\"42\" cy=\"56\" rx=\"30\" ry=\"36\" fill=\"#8a5a2f\"/><ellipse cx=\"42\" cy=\"66\" rx=\"19\" ry=\"23\" fill=\"#e9cf9f\"/><circle cx=\"29\" cy=\"38\" r=\"12\" fill=\"#f6ead0\"/><circle cx=\"55\" cy=\"38\" r=\"12\" fill=\"#f6ead0\"/><circle cx=\"29\" cy=\"39\" r=\"6\" fill=\"#2a1a0c\"/><circle cx=\"55\" cy=\"39\" r=\"6\" fill=\"#2a1a0c\"/><circle cx=\"29\" cy=\"38\" r=\"13\" fill=\"none\" stroke=\"#c9a14a\" stroke-width=\"1.6\"/><circle cx=\"55\" cy=\"38\" r=\"13\" fill=\"none\" stroke=\"#c9a14a\" stroke-width=\"1.6\"/><rect id=\"browL\" x=\"18\" y=\"22\" width=\"20\" height=\"3\" rx=\"1.5\" fill=\"#4a2c14\"/><rect id=\"browR\" x=\"46\" y=\"22\" width=\"20\" height=\"3\" rx=\"1.5\" fill=\"#4a2c14\"/><path d=\"M38 48 L46 48 L42 56Z\" fill=\"#e0a63a\"/></svg>\n          <p id=\"tryVerdict\">“Go on, I’m listening. Write me something true.”</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"papers\">\n    <div class=\"wrap\">\n      <div class=\"head\">\n        <p class=\"label\">Papers for every occasion</p>\n        <h2>Holiday stripes to company letterhead</h2>\n      </div>\n      <div class=\"papers\" id=\"paperGrid\"></div>\n      <p class=\"more\"><b>35 papers</b>, <b>7 layouts</b>, <b>160+ stickers</b> (florals, cars, Santa, birthday, roast and more), <b>8 wax seals</b>, and room for your own photos.</p>\n    </div>\n  </section>\n\n  <section id=\"pricing\" style=\"background:#1b1511\">\n    <div class=\"wrap\">\n      <div class=\"head\">\n        <p class=\"label\">Pricing</p>\n        <h2>Your first letter is on the house</h2>\n        <p class=\"lede\">Pay once, no subscription. Secure checkout by Stripe.</p>\n      </div>\n      <div class=\"plans\">\n        <div class=\"plan\">\n          <div class=\"pn\">Free</div>\n          <div class=\"price\">$0</div>\n          <div class=\"per\">1 letter</div>\n          <ul><li>Every paper and layout</li><li>Stickers, photos and seals</li><li>Quilliam’s stamp and share link</li></ul>\n          <a class=\"btn write-link\" href=\"/write\">Write your free letter</a>\n        </div>\n        <div class=\"plan\">\n          <div class=\"pn\">Holiday Pack</div>\n          <div class=\"price\">$4.99</div>\n          <div class=\"per\">10 letters, about 50¢ each</div>\n          <ul><li>Everything in Free</li><li>Letters never expire</li><li>Great for a family list</li></ul>\n          <a class=\"btn write-link\" href=\"/write?plans=1\">Get 10 letters</a>\n        </div>\n        <div class=\"plan best\">\n          <div class=\"pn\">Season Pass <span class=\"tag\">Most popular</span></div>\n          <div class=\"price\">$9.99</div>\n          <div class=\"per\">Unlimited letters until January 1</div>\n          <ul><li>Everything in Free</li><li>Every holiday, every friend</li><li>Roast cards included</li></ul>\n          <a class=\"btn write-link\" href=\"/write?plans=1\">Get the Season Pass</a>\n        </div>\n        <div class=\"plan\">\n          <div class=\"pn\">Business</div>\n          <div class=\"price\">$199<small>+</small></div>\n          <div class=\"per\">100+ letters for clients and teams</div>\n          <ul><li>Your logo, colors and seal</li><li>Bulk sending list</li><li>Invoice billing</li></ul>\n          <a class=\"btn\" href=\"#business\">Talk to us</a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"biz\" id=\"business\">\n    <div class=\"wrap\">\n      <div class=\"biz-copy\">\n        <p class=\"label\">For business</p>\n        <h2>Holiday notes your clients will keep</h2>\n        <p class=\"lede\">Every other card this December will be printed or written by a chatbot. Send handwritten notes on your own letterhead, with a certificate that a real person wrote each one.</p>\n        <div class=\"uses\">\n          <div><b>Client thank-yous</b><span>Year-end notes from the partner who handled the account</span></div>\n          <div><b>Team appreciation</b><span>A manager’s handwritten note to every report</span></div>\n          <div><b>Real estate and advisors</b><span>Closing-day and anniversary letters</span></div>\n          <div><b>Gifting add-on</b><span>A letter link to go with every gift box</span></div>\n        </div>\n        <form class=\"form\" id=\"bizForm\" novalidate>\n          <h3>Get a business quote</h3>\n          <div class=\"fields\">\n            <label for=\"bizName\">Your name<input id=\"bizName\" type=\"text\" maxlength=\"80\" autocomplete=\"name\" required></label>\n            <label for=\"bizCompany\">Company<input id=\"bizCompany\" type=\"text\" maxlength=\"100\" autocomplete=\"organization\" required></label>\n            <label for=\"bizEmail\">Work email<input id=\"bizEmail\" type=\"email\" maxlength=\"120\" autocomplete=\"email\" required></label>\n            <label for=\"bizCount\">How many letters?<select id=\"bizCount\"><option>Under 100</option><option selected>100–250</option><option>250–1,000</option><option>1,000+</option></select></label>\n          </div>\n          <button class=\"btn wax\" type=\"submit\" id=\"bizSubmit\">Request a quote</button>\n          <p class=\"formmsg\" id=\"bizMsg\" role=\"status\"></p>\n        </form>\n      </div>\n      <div class=\"lh\" aria-label=\"Example company letterhead\">\n        <div class=\"lh-head\"><div class=\"lh-logo\">N</div><div class=\"lh-name\">Northbeam Advisory<small>Wealth planning · Brooklyn</small></div></div>\n        <div class=\"lh-body\">Dear Priya,<br>Thank you for trusting us with your family’s plans this year. Your note about Leo’s first day of school made our whole team smile.<br><span style=\"display:block;text-align:right;margin-top:10px\">Warmly, Dan</span>\n          <img id=\"lhStamp\" alt=\"Quilliam certified stamp\" style=\"position:absolute;right:14px;top:8px;width:84px;transform:rotate(-12deg)\">\n        </div>\n        <div class=\"lh-foot\"><span>northbeam.example</span><span>Handwritten on Quilliam</span></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"mail\" id=\"mail\">\n    <div class=\"wrap\">\n      <div class=\"card\">\n        <svg class=\"env\" viewBox=\"0 0 64 44\" aria-hidden=\"true\"><rect x=\"1\" y=\"1\" width=\"62\" height=\"42\" rx=\"3\" fill=\"#fffaf0\" stroke=\"#c9a878\" stroke-width=\"2\"/><path d=\"M2 3l30 22L62 3\" fill=\"none\" stroke=\"#c9a878\" stroke-width=\"2\"/><circle cx=\"32\" cy=\"25\" r=\"7\" fill=\"#b3341f\"/><text x=\"32\" y=\"28.5\" text-anchor=\"middle\" font-size=\"9\" fill=\"#fff4e0\" font-family=\"Georgia,serif\">Q</text></svg>\n        <div>\n          <p class=\"label\" style=\"color:#9a5a1a\">Coming soon</p>\n          <h2>Want a real copy in the mail?</h2>\n          <p>We’re testing printed letters: your handwriting on thick paper, sealed in real wax and posted anywhere in the US. Join the list and we’ll tell you first.</p>\n          <form id=\"mailForm\" novalidate>\n            <label for=\"mailEmail\" class=\"label\" style=\"position:absolute;left:-9999px\">Email</label>\n            <input id=\"mailEmail\" type=\"email\" placeholder=\"you@example.com\" maxlength=\"120\" autocomplete=\"email\" required>\n            <button class=\"btn wax\" type=\"submit\" id=\"mailSubmit\">Join the list</button>\n          </form>\n          <p class=\"formmsg\" id=\"mailMsg\" role=\"status\" style=\"margin-top:10px\"></p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"faq\">\n    <div class=\"wrap\">\n      <div class=\"head\"><p class=\"label\">Questions</p><h2>Asked by humans</h2></div>\n      <div class=\"faq\">\n        <details open><summary>How does Quilliam know a person wrote it?</summary><p>He watches how the letter is made, not just what it says. Pen strokes, typing rhythm, pauses, backspaces and pasted text all count. A letter written stroke by stroke earns the stamp; a pasted block of text does not. Because the stamp comes from those signals, it doesn’t rely on guessing whether words “sound like AI.”</p></details>\n        <details><summary>Does my recipient need an account?</summary><p>No. They open the link in any browser and see your letter, the seal and Quilliam’s stamp. They can save it or write one back, and their first letter is free too.</p></details>\n        <details><summary>Can I type instead of handwriting?</summary><p>Yes. Typed letters can still earn the stamp when they’re typed, not pasted. Handwriting is the default because it’s the strongest proof and the most personal.</p></details>\n        <details><summary>Who can see my letter?</summary><p>Anyone with its link, so share it the way you’d share a photo. Links are long and random, and letters aren’t listed or searchable anywhere.</p></details>\n        <details><summary>Do Holiday Pack letters expire?</summary><p>No. Pack letters stay with the browser you bought them in until you use them. The Season Pass is unlimited until midnight on January 1 (New York time).</p></details>\n        <details><summary>Can my company use its own branding?</summary><p>Yes. The Company layout takes your logo, brand color and font, and can turn your logo into the wax seal. Request a quote above for volume pricing and invoicing.</p></details>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"final\">\n    <div class=\"wrap\">\n      <h2>Someone would love a letter from you</h2>\n      <p class=\"lede\">It takes three minutes. The first one is free.</p>\n      <a class=\"btn wax write-link\" href=\"/write\">Write a letter now</a>\n    </div>\n  </section>\n</main>\n\n<footer>\n  <div class=\"wrap\">\n    <span>© 2026 Quilliam · Made by hand in New York</span>\n    <nav aria-label=\"Footer\"><a href=\"#how\">How it works</a><a href=\"#pricing\">Pricing</a><a href=\"#business\">For business</a><a href=\"#faq\">FAQ</a></nav>\n  </div>\n</footer>\n\n<script>\n(() => {\nconst $ = id => document.getElementById(id);\nconst svgURI = s => \"data:image/svg+xml;charset=utf-8,\" + encodeURIComponent(s.startsWith(\"<svg\") ? s : `<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\">${s}</svg>`);\nconst HOSTED = typeof window.QUILLIAM_API === \"string\";\nconst API = HOSTED ? window.QUILLIAM_API : null;\nconst DEMO_APP = \"https://claude.ai/artifact/QtpwZyu9vDfXX9NzCdGcHj\";\n\n// In the preview (not on the real site), point write links at the demo app.\nif (!HOSTED) document.querySelectorAll(\".write-link\").forEach(a => { a.href = DEMO_APP; a.target = \"_blank\"; a.rel = \"noopener\"; });\n\n/* Art */\nconst seal = (c,d,g) => `<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 80 80\"><path d=\"M40 4 l7 5 8-2 4 7 8 2 1 8 6 5-3 8 3 8-6 5-1 8-8 2-4 7-8-2-7 5-7-5-8 2-4-7-8-2-1-8-6-5 3-8-3-8 6-5 1-8 8-2 4-7 8 2z\" fill=\"${d}\"/><circle cx=\"40\" cy=\"40\" r=\"27\" fill=\"${c}\"/><circle cx=\"40\" cy=\"40\" r=\"21\" fill=\"none\" stroke=\"${d}\" stroke-width=\"2\"/><text x=\"40\" y=\"49\" text-anchor=\"middle\" font-family=\"Georgia,serif\" font-size=\"24\" fill=\"#fff4e0\" opacity=\".9\">${g}</text></svg>`;\nconst stamp = color => { const t = \"WRITTEN BY A HUMAN HAND · CERTIFIED BY QUILLIAM · \"; return `<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 200 200\"><defs><path id=\"c\" d=\"M100,100 m-78,0 a78,78 0 1,1 156,0 a78,78 0 1,1 -156,0\"/></defs><g fill=\"none\" stroke=\"${color}\" opacity=\".92\"><circle cx=\"100\" cy=\"100\" r=\"94\" stroke-width=\"5\"/><circle cx=\"100\" cy=\"100\" r=\"64\" stroke-width=\"2.5\"/></g><text font-family=\"Arial,sans-serif\" font-weight=\"700\" font-size=\"12.6\" letter-spacing=\"1.2\" fill=\"${color}\" opacity=\".92\"><textPath href=\"#c\">${t}</textPath></text><text x=\"100\" y=\"108\" text-anchor=\"middle\" font-family=\"Georgia,serif\" font-style=\"italic\" font-weight=\"700\" font-size=\"58\" fill=\"${color}\" opacity=\".92\">Q</text><text x=\"100\" y=\"134\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" font-weight=\"700\" font-size=\"11\" letter-spacing=\"1.5\" fill=\"${color}\" opacity=\".92\">2026 · VERIFIED</text></svg>`; };\n$(\"heroSeal\").src = svgURI(seal(\"#b3341f\", \"#7e1d0f\", \"♥\"));\n$(\"heroStamp\").src = svgURI(stamp(\"#f3e6c4\"));\n$(\"stepStamp\").src = svgURI(stamp(\"#9be7c2\"));\n$(\"lhStamp\").src = svgURI(stamp(\"#1f4fa8\"));\n$(\"heroStk1\").src = svgURI(`<rect x=\"27\" y=\"6\" width=\"10\" height=\"8\" rx=\"2\" fill=\"#c9952e\"/><circle cx=\"32\" cy=\"38\" r=\"22\" fill=\"#c4234a\"/><path d=\"M12 34h40M14 44h36\" stroke=\"#f4d27a\" stroke-width=\"3\"/><circle cx=\"24\" cy=\"30\" r=\"4\" fill=\"#fff6\"/>`);\n$(\"heroStk2\").src = svgURI(`<g stroke=\"#cfe3f5\" stroke-width=\"3.5\" stroke-linecap=\"round\" fill=\"none\"><path d=\"M32 6v52M9.5 19l45 26M9.5 45l45-26M26 10l6 6 6-6M26 54l6-6 6 6\"/></g>`);\n\n/* Paper grid (the same papers the app ships with) */\nconst PAPERS = [\n  [\"Evergreen\",\"Christmas\",\"linear-gradient(160deg,#21402f,#152b20)\",\"#f3e6c4\",\"'Pinyon Script',cursive\",\"Dearest Maya,\"],\n  [\"Candy Cane\",\"Christmas\",\"repeating-linear-gradient(45deg,#d8283f 0 10px,#fffaf6 10px 20px) top/100% 12px no-repeat,#fffaf6\",\"#8e1426\",\"'Pinyon Script',cursive\",\"Dear Sam,\"],\n  [\"Diya Glow\",\"Diwali\",\"radial-gradient(120% 80% at 50% 100%,#5a2348,#2a1338 70%)\",\"#ffd77f\",\"'Cormorant Garamond',serif\",\"Dear Anu,\"],\n  [\"Harvest Table\",\"Thanksgiving\",\"linear-gradient(180deg,#f5e7d3,#ead2b4)\",\"#6b2f12\",\"'Cormorant Garamond',serif\",\"Dear Grandma,\"],\n  [\"Birthday Confetti\",\"Birthday\",\"radial-gradient(circle,#f29bb8 3px,transparent 3.5px) 0 0/34px 34px,radial-gradient(circle,#7fb3e0 3px,transparent 3.5px) 17px 17px/34px 34px,#fffdf8\",\"#7a2c4a\",\"'Pinyon Script',cursive\",\"Happy birthday!\"],\n  [\"Ivory & Gold\",\"Anniversary\",\"linear-gradient(#c9a14a,#c9a14a) 8px 8px/calc(100% - 16px) 2px no-repeat,linear-gradient(#c9a14a,#c9a14a) 8px calc(100% - 10px)/calc(100% - 16px) 2px no-repeat,#fbf7ee\",\"#6e4f1c\",\"'Pinyon Script',cursive\",\"My love,\"],\n  [\"Ember Roast\",\"Roast card\",\"radial-gradient(120% 70% at 50% 110%,#7a2a0c,#1c0f0b 70%)\",\"#ffb27a\",\"'Fraunces',serif\",\"ROASTED\"],\n  [\"Airmail\",\"Travel postcard\",\"repeating-linear-gradient(135deg,#c0392b 0 12px,#f6f4ee 12px 20px,#1f4fa8 20px 32px,#f6f4ee 32px 40px) top/100% 9px no-repeat,#f6f4ee\",\"#1f3a6e\",\"'Special Elite',monospace\",\"Wish you were here\"],\n];\n$(\"paperGrid\").innerHTML = PAPERS.map(([n,s,bg,ink,f,g]) => `<div class=\"pc\"><div class=\"sheet\" style=\"background:${bg};color:${ink}\"><b style=\"font-family:${f}\">${g}</b><i></i><i></i><i></i></div><div><strong>${n}</strong><small>${s}</small></div></div>`).join(\"\");\n$(\"stepSwatches\").innerHTML = PAPERS.slice(0,4).map(p => `<div style=\"background:${p[2]}\"></div>`).join(\"\");\n\n/* Try-Quilliam demo: the same kinds of signals the app uses */\nconst CLICHES = [\"delve\",\"tapestry\",\"testament to\",\"hope this message finds you\",\"hope this letter finds you\",\"fast-paced\",\"navigate the\",\"heartfelt gratitude\",\"cherish the memories\",\"embark\",\"beacon\",\"unwavering\",\"profound\",\"journey together\",\"—\"];\nconst ta = $(\"tryText\"); let keys = 0, backs = 0, pasted = 0, gaps = [], last = 0, timer = null;\nconst LINES = {\n  idle:\"“Go on, I’m listening. Write me something true.”\",\n  human:[\"“A real detail! Cardamom and a kitchen. That’s a person talking.”\",\"“Typed slowly, fixed twice. Human through and through.”\",\"“Specific, a bit crooked, entirely yours. Splendid.”\"],\n  meh:[\"“Hmm. Rather tidy. Tell me one thing only you would know.”\",\"“Fine words, but where’s the memory? Give me a name, a place.”\"],\n  robot:[\"“Did you just paste that? I can smell the server farm from here.”\",\"“‘Delve’? Nobody who loves someone has ever said delve.”\",\"“This reads like a terms-of-service agreement wearing a Santa hat.”\"]\n};\nlet qi = 0;\nfunction score(){\n  const t = ta.value, low = t.toLowerCase();\n  if (!t.trim()) return null;\n  const cl = CLICHES.filter(c => low.includes(c)).length;\n  const pr = Math.min(1, pasted / Math.max(1, t.length));\n  let s = 50 - Math.min(26, keys / 5) - Math.min(10, backs * 2) + pr * 70 + cl * 12;\n  if (/\\b(mom|dad|grandma|kitchen|remember|last year|our|we got|smelled|laughed)\\b/i.test(t)) s -= 10;\n  return Math.max(4, Math.min(96, s));\n}\nfunction react(){\n  const s = score(); const pin = $(\"tryPin\");\n  if (s === null){ pin.style.left = \"50%\"; $(\"tryVerdict\").textContent = LINES.idle; setBrows(false); return; }\n  pin.style.left = s + \"%\";\n  const pool = s > 62 ? LINES.robot : s > 40 ? LINES.meh : LINES.human;\n  $(\"tryVerdict\").textContent = pool[qi++ % pool.length]; setBrows(s > 62);\n}\nfunction setBrows(angry){ $(\"browL\").setAttribute(\"transform\", angry ? \"rotate(14 28 23.5)\" : \"\"); $(\"browR\").setAttribute(\"transform\", angry ? \"rotate(-14 56 23.5)\" : \"\"); }\nta.addEventListener(\"keydown\", e => { if (e.key === \"Backspace\") backs++; else if (e.key.length === 1){ keys++; const n = performance.now(); if (last) gaps.push(n - last); last = n; } });\nta.addEventListener(\"paste\", e => { pasted += ((e.clipboardData && e.clipboardData.getData(\"text\")) || \"\").length; setTimeout(react, 0); });\nta.addEventListener(\"input\", () => { clearTimeout(timer); timer = setTimeout(react, 900); });\nfunction reset(){ ta.value = \"\"; keys = backs = pasted = 0; gaps = []; last = 0; }\n$(\"tryClear\").onclick = () => { reset(); react(); ta.focus(); };\n$(\"tryRobot\").onclick = () => { reset(); const t = \"I hope this message finds you well. As we navigate the complexities of this festive season, I wanted to express my heartfelt gratitude — you are a beacon of unwavering support.\"; ta.value = t; pasted = t.length; react(); };\n$(\"tryHuman\").onclick = () => { reset(); const t = \"Dear Mom, the kitchen smelled like cardamom today and I almost called you to ask how long the kheer goes. Miss you. Burnt it anyway\"; let i = 0; keys = 0;\n  const step = () => { if (i <= t.length){ ta.value = t.slice(0, i); keys = i; if (i === 60) backs = 2; i += 3; setTimeout(step, 18); } else react(); };\n  if (matchMedia(\"(prefers-reduced-motion: reduce)\").matches){ ta.value = t; keys = t.length; backs = 2; react(); } else step(); };\n\n/* Forms */\nconst emailOK = v => /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(v);\nasync function post(path, body){\n  const r = await fetch(API + path, { method:\"POST\", headers:{ \"content-type\":\"application/json\" }, body: JSON.stringify(body) });\n  if (!r.ok) throw new Error(\"http \" + r.status);\n}\nfunction msg(el, text, ok){ el.textContent = text; el.className = \"formmsg \" + (ok ? \"ok\" : \"err\"); }\n$(\"bizForm\").addEventListener(\"submit\", async e => {\n  e.preventDefault();\n  const name = $(\"bizName\").value.trim(), company = $(\"bizCompany\").value.trim(), email = $(\"bizEmail\").value.trim(), m = $(\"bizMsg\");\n  if (!name || !company) return msg(m, \"Add your name and company so we know who to write to.\", false);\n  if (!emailOK(email)) return msg(m, \"Enter a work email like name@company.com.\", false);\n  if (!HOSTED) return msg(m, \"Preview only: on the live site this sends your request to the Quilliam team.\", true);\n  const b = $(\"bizSubmit\"); b.disabled = true; b.textContent = \"Sending…\";\n  try { await post(\"/api/business-lead\", { name, company, email, size: $(\"bizCount\").value }); msg(m, \"Thanks, \" + name.split(\" \")[0] + \". We’ll be in touch soon.\", true); $(\"bizForm\").reset(); }\n  catch { msg(m, \"That didn’t send. Check your connection and try again.\", false); }\n  b.disabled = false; b.textContent = \"Request a quote\";\n});\n$(\"mailForm\").addEventListener(\"submit\", async e => {\n  e.preventDefault();\n  const email = $(\"mailEmail\").value.trim(), m = $(\"mailMsg\");\n  if (!emailOK(email)) return msg(m, \"Enter an email like you@example.com.\", false);\n  if (!HOSTED) return msg(m, \"Preview only: on the live site this adds you to the list.\", true);\n  const b = $(\"mailSubmit\"); b.disabled = true; b.textContent = \"Joining…\";\n  try { await post(\"/api/mail-request\", { email, occasion: \"Landing page waitlist\" }); msg(m, \"You’re on the list. We’ll email you when mailed letters launch.\", true); $(\"mailForm\").reset(); }\n  catch { msg(m, \"That didn’t go through. Try again in a minute.\", false); }\n  b.disabled = false; b.textContent = \"Join the list\";\n});\n})();\n<\/script>\n</body></html>";

export default {
  async fetch(req, env) {
    try { return await route(req, env); }
    catch (e) { console.error(e && e.stack || e); return json({ error: "server_error" }, 500); }
  },
};

async function route(req, env) {
  const url = new URL(req.url);
  const p = url.pathname;
  if (req.method === "GET" && (p === "/" || p === "/index.html")) return page(LANDING_HTML);
  if (req.method === "GET" && (p === "/write" || p === "/write/")) return page(APP_HTML);
  if (req.method === "GET" && p.startsWith("/l/")) return letterPage(p.slice(3), url, env);
  if (req.method === "GET" && p.startsWith("/img/")) return letterImage(p.slice(5), env);
  if (req.method === "GET" && p === "/api/health")
    return json({ ok: true, db: !!env.DB, letters: !!env.LETTERS, stripe: !!env.STRIPE_SECRET_KEY, webhook: !!env.STRIPE_WEBHOOK_SECRET,
                  stripe_mode: env.STRIPE_SECRET_KEY ? (env.STRIPE_SECRET_KEY.startsWith("sk_live") ? "live" : "test") : null });
  if (req.method === "POST") {
    if (p === "/api/stripe-webhook") return webhook(req, env);
    const body = await readJson(req);
    if (body === null) return json({ error: "bad_request" }, 400);
    if (p === "/api/me") return me(body, env);
    if (p === "/api/checkout") return checkout(body, url, env);
    if (p === "/api/confirm") return confirm(body, env);
    if (p === "/api/seal") return seal(body, url, env);
    if (p === "/api/mail-request") return mailRequest(body, env);
    if (p === "/api/business-lead") return businessLead(body, env);
  }
  return new Response("Not found", { status: 404 });
}

/* ---------- accounts ---------- */
const TOKEN_RE = /^[a-f0-9]{48}$/;
function randomHex(bytes) { const a = crypto.getRandomValues(new Uint8Array(bytes)); return [...a].map(b => b.toString(16).padStart(2, "0")).join(""); }
function randomId() { const a = crypto.getRandomValues(new Uint8Array(12)); return btoa(String.fromCharCode(...a)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, ""); }

async function account(env, token) {
  if (!token || !TOKEN_RE.test(token)) return null;
  const row = await env.DB.prepare("SELECT token, credits, season_until FROM buyers WHERE token = ?").bind(token).first();
  if (!row) return null;
  return { token: row.token, credits: row.credits, season: !!row.season_until && row.season_until > new Date().toISOString(), season_until: row.season_until };
}

async function me(body, env) {
  const existing = await account(env, body.token);
  if (existing) return json(existing);
  const token = randomHex(24);
  await env.DB.prepare("INSERT INTO buyers (token, credits) VALUES (?, ?)").bind(token, FREE_LETTERS).run();
  return json(await account(env, token));
}

/* ---------- Stripe ---------- */
async function stripe(env, method, path, form) {
  const r = await fetch("https://api.stripe.com/v1" + path, {
    method,
    headers: { Authorization: "Bearer " + env.STRIPE_SECRET_KEY, "Content-Type": "application/x-www-form-urlencoded" },
    body: form ? form.toString() : undefined,
  });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) { const e = new Error("stripe " + r.status + " " + (j.error && j.error.message)); e.stripe = j; throw e; }
  return j;
}

async function checkout(body, url, env) {
  if (!env.STRIPE_SECRET_KEY) return json({ error: "stripe_not_configured" }, 503);
  const plan = PLANS[body.plan];
  if (!plan) return json({ error: "unknown_plan" }, 400);
  const acct = await account(env, body.token);
  if (!acct) return json({ error: "unknown_buyer" }, 400);
  const f = new URLSearchParams();
  f.set("mode", "payment");
  f.set("line_items[0][quantity]", "1");
  f.set("line_items[0][price_data][currency]", "usd");
  f.set("line_items[0][price_data][unit_amount]", String(plan.amount));
  f.set("line_items[0][price_data][product_data][name]", plan.name);
  f.set("success_url", url.origin + "/write?paid={CHECKOUT_SESSION_ID}");
  f.set("cancel_url", url.origin + "/write?canceled=1");
  f.set("client_reference_id", acct.token);
  f.set("metadata[token]", acct.token);
  f.set("metadata[plan]", body.plan);
  f.set("allow_promotion_codes", "true");
  const session = await stripe(env, "POST", "/checkout/sessions", f);
  return json({ url: session.url });
}

// Records a paid Checkout Session once, however many times Stripe or the browser reports it.
async function grant(env, session) {
  if (!session || session.payment_status !== "paid") return false;
  const token = session.metadata && session.metadata.token;
  const planKey = session.metadata && session.metadata.plan;
  const plan = PLANS[planKey];
  if (!plan || !TOKEN_RE.test(token || "")) return false;
  const email = session.customer_details && session.customer_details.email || null;
  const ins = await env.DB.prepare("INSERT OR IGNORE INTO purchases (session_id, token, plan, amount_cents, email) VALUES (?, ?, ?, ?, ?)")
    .bind(session.id, token, planKey, session.amount_total ?? plan.amount, email).run();
  if (!ins.meta || ins.meta.changes !== 1) return true; // already granted
  if (plan.season) await env.DB.prepare("UPDATE buyers SET season_until = ? WHERE token = ?").bind(SEASON_END, token).run();
  else await env.DB.prepare("UPDATE buyers SET credits = credits + ? WHERE token = ?").bind(plan.credits, token).run();
  return true;
}

async function confirm(body, env) {
  if (!env.STRIPE_SECRET_KEY) return json({ error: "stripe_not_configured" }, 503);
  const acct = await account(env, body.token);
  if (!acct || typeof body.session_id !== "string" || !/^cs_[A-Za-z0-9_]+$/.test(body.session_id)) return json({ error: "bad_request" }, 400);
  const session = await stripe(env, "GET", "/checkout/sessions/" + body.session_id);
  if (!session.metadata || session.metadata.token !== acct.token) return json({ error: "not_yours" }, 403);
  if (session.payment_status !== "paid") return json({ error: "not_paid" }, 409);
  await grant(env, session);
  return json({ plan: session.metadata.plan, account: await account(env, acct.token) });
}

async function webhook(req, env) {
  if (!env.STRIPE_WEBHOOK_SECRET) return json({ error: "webhook_not_configured" }, 503);
  const raw = await req.text();
  const ok = await verifyStripeSignature(raw, req.headers.get("stripe-signature") || "", env.STRIPE_WEBHOOK_SECRET);
  if (!ok) return json({ error: "bad_signature" }, 400);
  const event = JSON.parse(raw);
  if (event.type === "checkout.session.completed" || event.type === "checkout.session.async_payment_succeeded") {
    await grant(env, event.data.object);
  }
  return json({ received: true });
}

async function verifyStripeSignature(payload, header, secret) {
  const parts = Object.create(null);
  const v1 = [];
  for (const kv of header.split(",")) {
    const i = kv.indexOf("="); if (i < 0) continue;
    const k = kv.slice(0, i).trim(), v = kv.slice(i + 1).trim();
    if (k === "v1") v1.push(v); else parts[k] = v;
  }
  const t = Number(parts.t);
  if (!t || !v1.length || Math.abs(Date.now() / 1000 - t) > 300) return false;
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(t + "." + payload)));
  const expected = [...sig].map(b => b.toString(16).padStart(2, "0")).join("");
  return v1.some(s => timingSafeEqual(s, expected));
}
function timingSafeEqual(a, b) { if (a.length !== b.length) return false; let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i); return r === 0; }

/* ---------- letters ---------- */
async function seal(body, url, env) {
  const acct = await account(env, body.token);
  if (!acct) return json({ error: "unknown_buyer" }, 400);
  if (!acct.season && acct.credits < 1) return json({ error: "no_credits", account: acct }, 402);
  const m = typeof body.image === "string" && body.image.match(/^data:(image\/(?:jpeg|png));base64,([A-Za-z0-9+/=]+)$/);
  if (!m) return json({ error: "bad_image" }, 400);
  const bytes = Uint8Array.from(atob(m[2]), c => c.charCodeAt(0));
  if (bytes.length > MAX_IMAGE_BYTES) return json({ error: "too_large" }, 413);

  if (!acct.season) {
    const spent = await env.DB.prepare("UPDATE buyers SET credits = credits - 1 WHERE token = ? AND credits > 0").bind(acct.token).run();
    if (!spent.meta || spent.meta.changes !== 1) return json({ error: "no_credits", account: await account(env, acct.token) }, 402);
  }
  const id = randomId();
  const meta = body.meta || {};
  const clip = (v, n) => (typeof v === "string" ? v.slice(0, n) : null);
  try {
    await env.LETTERS.put("img:" + id, bytes, { metadata: { type: m[1] } });
    await env.DB.prepare("INSERT INTO letters (id, token, to_name, from_name, paper, layout, certified, strokes, words) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .bind(id, acct.token, clip(meta.to, 40), clip(meta.from, 40), clip(meta.paper, 40), clip(meta.layout, 20),
            meta.certified ? 1 : 0, Number(meta.strokes) || 0, Number(meta.words) || 0).run();
  } catch (e) {
    if (!acct.season) await env.DB.prepare("UPDATE buyers SET credits = credits + 1 WHERE token = ?").bind(acct.token).run();
    throw e;
  }
  return json({ id, url: url.origin + "/l/" + id, account: await account(env, acct.token) });
}

async function letterImage(id, env) {
  if (!/^[A-Za-z0-9_-]{16}$/.test(id)) return new Response("Not found", { status: 404 });
  const { value, metadata } = await env.LETTERS.getWithMetadata("img:" + id, { type: "arrayBuffer" });
  if (!value) return new Response("Not found", { status: 404 });
  return new Response(value, { headers: { "Content-Type": (metadata && metadata.type) || "image/jpeg", "Cache-Control": "public, max-age=31536000, immutable" } });
}

async function letterPage(id, url, env) {
  const row = /^[A-Za-z0-9_-]{16}$/.test(id) ? await env.DB.prepare("SELECT * FROM letters WHERE id = ?").bind(id).first() : null;
  if (!row) return page(shell("Letter not found", `<main class="wrap"><h1>This letter isn’t here</h1><p>The link may be mistyped. <a href="/write">Write a letter of your own</a>.</p></main>`, ""), 404);
  const from = esc(row.from_name || "Someone");
  const to = esc(row.to_name || "you");
  const img = url.origin + "/img/" + row.id;
  const title = `${from} wrote ${to} a letter`;
  const og = `<meta property="og:title" content="${title}"><meta property="og:description" content="Handwritten on Quilliam${row.certified ? ", certified human-written" : ""}."><meta property="og:image" content="${img}"><meta name="twitter:card" content="summary_large_image">`;
  const body = `<main class="wrap">
    <p class="eyebrow">A letter for ${to}</p>
    <h1>${from} wrote you a letter</h1>
    ${row.certified ? `<p class="cert">✓ Quilliam-certified: written by a human hand</p>` : ""}
    <img class="letter" src="/img/${row.id}" alt="Handwritten letter from ${from} to ${to}">
    <div class="row">
      <a class="btn primary" href="/write?to=${encodeURIComponent(row.from_name || "")}">Write ${from} one back</a>
      <a class="btn" href="/img/${row.id}" download="letter-from-${(row.from_name || "a-friend").replace(/[^a-z0-9]+/gi, "-").toLowerCase()}.jpg">Save the letter</a>
    </div>
    <p class="fine">Your first letter on Quilliam is free.</p>
  </main>`;
  return page(shell(title, body, og));
}

/* ---------- mailed-letter interest ---------- */
async function mailRequest(body, env) {
  const email = typeof body.email === "string" ? body.email.trim().slice(0, 120) : "";
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return json({ error: "bad_email" }, 400);
  const clip = (v) => (typeof v === "string" ? v.slice(0, 40) : null);
  await env.DB.prepare("INSERT INTO mail_requests (email, price, occasion, paper, layout) VALUES (?, ?, ?, ?, ?)")
    .bind(email, clip(body.price), clip(body.occasion), clip(body.paper), clip(body.layout)).run();
  return json({ ok: true });
}

/* ---------- business leads ---------- */
async function businessLead(body, env) {
  const clip = (v, n) => (typeof v === "string" ? v.trim().slice(0, n) : "");
  const name = clip(body.name, 80), company = clip(body.company, 100), email = clip(body.email, 120), size = clip(body.size, 40);
  if (!name || !company || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return json({ error: "bad_request" }, 400);
  await env.DB.prepare("INSERT INTO business_leads (name, company, email, size) VALUES (?, ?, ?, ?)").bind(name, company, email, size).run();
  return json({ ok: true });
}

/* ---------- helpers ---------- */
async function readJson(req) {
  const len = Number(req.headers.get("content-length") || 0);
  if (len > 7 * 1024 * 1024) return null;
  try { const j = await req.json(); return j && typeof j === "object" ? j : null; } catch { return null; }
}
function json(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" } });
}
function page(html, status = 200) {
  return new Response(html, { status, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff", "Referrer-Policy": "strict-origin-when-cross-origin" } });
}
function esc(s) { return String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])); }
function shell(title, body, head) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>${title}</title>${head}
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@1,9..144,800&family=Manrope:wght@500;700&display=swap">
<style>
:root{color-scheme:dark}
body{margin:0;background:radial-gradient(1000px 500px at 30% -10%,#3a2a1c55,transparent 70%),#1a1512;color:#f1e7da;font:15px/1.5 Manrope,system-ui,sans-serif}
.wrap{max-width:760px;margin:0 auto;padding:28px max(16px,env(safe-area-inset-left)) 60px max(16px,env(safe-area-inset-right));display:grid;gap:14px}
.eyebrow{margin:0;font:12px "Courier New",monospace;letter-spacing:.2em;text-transform:uppercase;color:#e0a63a}
h1{margin:0;font:italic 800 clamp(30px,6vw,46px)/1.05 Fraunces,Georgia,serif;text-wrap:balance}
.cert{margin:0;color:#8fe0b8;font-weight:700}
.letter{width:100%;height:auto;border-radius:8px;box-shadow:0 24px 50px #0009}
.row{display:flex;flex-wrap:wrap;gap:10px}
.btn{display:inline-block;border:1px solid #3a3029;background:#231c17;color:#f1e7da;border-radius:12px;padding:12px 18px;font-weight:700;text-decoration:none}
.btn.primary{background:linear-gradient(180deg,#b3341f,#8e2414);border-color:#b3341f;color:#fff3e8}
.fine{color:#a6978a;font-size:13px;margin:0} a{color:#e0a63a}
</style></head><body>${body}</body></html>`;
}
